#!/usr/bin/env python3
"""Monitor the bounded issue 662 comparator run through gh_common only."""

from __future__ import annotations

import json
import os
import sys
import time
from datetime import datetime, timezone

sys.path.insert(0, "/home/drx/MIPStarRE-qpbt/local/bin")
os.environ["MIPSTARRE_GITHUB_REPO"] = "Dengnifer/QPBT-comparator"

import gh_common


RUN_ID = 35621468975
POLL_SECONDS = 120


def read_state() -> dict:
    run = gh_common.api(f"actions/runs/{RUN_ID}")
    jobs = gh_common.api(f"actions/runs/{RUN_ID}/jobs?per_page=100").get("jobs", [])
    return {
        "observed_at": datetime.now(timezone.utc).isoformat(),
        "run": {
            key: run.get(key)
            for key in (
                "id",
                "name",
                "path",
                "event",
                "status",
                "conclusion",
                "head_branch",
                "head_sha",
                "run_number",
                "run_attempt",
                "created_at",
                "run_started_at",
                "updated_at",
                "html_url",
                "workflow_id",
            )
        },
        "jobs": [
            {
                "id": job.get("id"),
                "name": job.get("name"),
                "status": job.get("status"),
                "conclusion": job.get("conclusion"),
                "started_at": job.get("started_at"),
                "completed_at": job.get("completed_at"),
                "html_url": job.get("html_url"),
                "steps": [
                    {
                        key: step.get(key)
                        for key in (
                            "number",
                            "name",
                            "status",
                            "conclusion",
                            "started_at",
                            "completed_at",
                        )
                    }
                    for step in job.get("steps", [])
                ],
            }
            for job in jobs
        ],
    }


def main() -> int:
    while True:
        try:
            state = read_state()
        except Exception as error:
            print(
                json.dumps(
                    {
                        "observed_at": datetime.now(timezone.utc).isoformat(),
                        "monitor_error": str(error),
                    },
                    sort_keys=True,
                ),
                flush=True,
            )
            time.sleep(POLL_SECONDS)
            continue

        print(json.dumps(state, sort_keys=True), flush=True)
        run = state["run"]
        if run["status"] == "completed":
            return 0 if run["conclusion"] == "success" else 1
        time.sleep(POLL_SECONDS)


if __name__ == "__main__":
    raise SystemExit(main())

